import { defineExperience, startExperience, type GeneratedFrame, type GeneratedMountContext, type GeneratedViewport } from '@signal-lab/experience-sdk';
import { createGreenhouseScene, type GreenhouseScene } from './scene';
import { direct } from './director';

let scene: GreenhouseScene | null = null;
let shell: HTMLElement | null = null;

function buildPage(container: HTMLElement): HTMLElement {
  const page = document.createElement('div');
  page.className = 'night-greenhouse';
  page.style.setProperty('--story', '0');
  page.style.setProperty('--middle', '0');
  page.innerHTML = `
    <div class="mature-environment" aria-hidden="true"></div>
    <div class="transition-environment" aria-hidden="true"></div>
    <img class="seed-pod-plate" src="/creative-assets/biomaterial-seed-pod-plate-v1.png" alt="" aria-hidden="true">
    <main class="copy-layer">
      <section class="hero-copy" aria-labelledby="page-title">
        <p class="eyebrow">NOCTURNE MATERIAL HOUSE · 2026</p>
        <h1 id="page-title">夜生表皮，<br>从一枚种子开始呼吸</h1>
        <p class="lede">一座仅在夜间开放的生物材料温室。为建筑师与材料研究者呈现纤维如何从培养基中聚合，成为可被信任的空间表皮。</p>
        <a class="primary-action" href="#visit">预约夜访 <span aria-hidden="true">↗</span></a>
      </section>
      <section class="scroll-note" aria-label="叙事进度"><span>01—03</span><i></i><span>向下阅读</span></section>
      <section class="research-note"><p>培养中的菌丝纤维<br>低照度观察 / 22:00—01:00</p></section>
      <section class="final-copy" id="visit" aria-labelledby="visit-title">
        <p class="eyebrow">NIGHT VISITATION</p>
        <h2 id="visit-title">一层会呼吸的安静穹顶</h2>
        <p>走入成熟表皮围合的中庭，查看材料样本、透湿性能与实际尺度构件。每晚限额十二位。</p>
        <a class="secondary-action" href="mailto:visit@nocturnematerial.house?subject=Night%20Greenhouse%20Visit">申请参观席位</a>
      </section>
    </main>`;
  container.appendChild(page);
  return page;
}

function mount(context: GeneratedMountContext): void {
  shell = buildPage(context.container);
  shell.classList.toggle('is-reduced-motion', context.reducedMotion);
  try {
    scene = createGreenhouseScene(context.canvas, context.quality, context.reducedMotion, context.viewport);
  } catch {
    shell.classList.add('webgl-fallback');
    scene = null;
  }
}

function update(frame: GeneratedFrame): void {
  if (!shell) return;
  const state = direct(frame.progress, frame.pointer, frame.elapsed, frame.reducedMotion);
  shell.style.setProperty('--story', state.story.toFixed(3));
  shell.style.setProperty('--middle', Math.max(0, 1 - Math.abs(state.story - 0.44) / 0.24).toFixed(3));
  scene?.render(state);
}

function resize(viewport: GeneratedViewport): void {
  scene?.resize(viewport);
}

function dispose(): void {
  scene?.dispose();
  scene = null;
  shell?.remove();
  shell = null;
}

startExperience(defineExperience({ mount, update, resize, dispose }));

import * as THREE from 'three';

export interface Direction {
  story: number;
  seedScale: number;
  fiberAssembly: number;
  greenhouseReveal: number;
  canopyBreath: number;
  seedPosition: THREE.Vector3;
  camera: THREE.Vector3;
  target: THREE.Vector3;
}

const camera = new THREE.Vector3();
const target = new THREE.Vector3();
const seedPosition = new THREE.Vector3();

function smoothstep(a: number, b: number, value: number): number {
  const t = THREE.MathUtils.clamp((value - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

export function direct(progress: number, pointer: { x: number; y: number }, elapsed: number, reducedMotion: boolean): Direction {
  const story = THREE.MathUtils.clamp(progress, 0, 1);
  const assemble = smoothstep(0.12, 0.72, story);
  const arrive = smoothstep(0.64, 0.98, story);
  const drift = reducedMotion ? 0 : Math.sin(elapsed * 0.62) * 0.028 * (1 - arrive);
  const lookX = reducedMotion ? 0 : pointer.x * 0.08;
  const lookY = reducedMotion ? 0 : pointer.y * 0.045;

  camera.set(lookX * (1 - arrive), 0.24 + lookY + arrive * 0.16, 8.15 - arrive * 1.55);
  target.set(0, 0.08 + arrive * 0.1 + drift, -0.5 - arrive * 0.72);
  seedPosition.set(0.68 - story * 0.72, 0.18 + story * 0.08 + drift, -0.08 - story * 0.62);

  return {
    story,
    seedScale: 0.92 + assemble * 0.2 - arrive * 0.34,
    fiberAssembly: assemble,
    greenhouseReveal: arrive,
    canopyBreath: reducedMotion ? 0 : Math.sin(elapsed * 0.82) * 0.018 * assemble * (1 - arrive),
    seedPosition,
    camera,
    target
  };
}

import * as THREE from 'three';
import type { GeneratedViewport } from '@signal-lab/experience-sdk';
import type { Direction } from './director';

export interface GreenhouseScene {
  render(direction: Direction): void;
  resize(viewport: GeneratedViewport): void;
  dispose(): void;
}

type FiberMeta = {
  family: 'longitudinal' | 'transverse';
  index: number;
  total: number;
  points: number;
  phase: number;
};

function smooth01(value: number): number {
  const t = THREE.MathUtils.clamp(value, 0, 1);
  return t * t * (3 - 2 * t);
}

export function createGreenhouseScene(canvas: HTMLCanvasElement, quality: 'low' | 'balanced' | 'high', reducedMotion: boolean, viewport: GeneratedViewport): GreenhouseScene {
  const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: quality !== 'low' });
  renderer.setClearColor(0x000000, 0);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.04;
  renderer.setPixelRatio(Math.min(viewport.dpr, quality === 'low' ? 1.25 : 2));
  renderer.setSize(viewport.width, viewport.height, false);

  const world = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(38, viewport.width / viewport.height, 0.1, 40);
  const geometries = new Set<THREE.BufferGeometry>();
  const materials = new Set<THREE.Material>();

  const fibers = new THREE.Group();
  const longitudinalMaterial = new THREE.LineBasicMaterial({
    color: 0xe0e3d5,
    transparent: true,
    opacity: 0,
    depthWrite: false,
    blending: THREE.AdditiveBlending
  });
  const transverseMaterial = new THREE.LineBasicMaterial({
    color: 0xb8c5ad,
    transparent: true,
    opacity: 0,
    depthWrite: false,
    blending: THREE.AdditiveBlending
  });
  materials.add(longitudinalMaterial);
  materials.add(transverseMaterial);

  const longitudinalCount = quality === 'low' ? 8 : 12;
  const transverseCount = quality === 'low' ? 4 : 6;
  const pointCount = quality === 'low' ? 28 : 42;

  function addFiber(family: FiberMeta['family'], index: number, total: number): void {
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(pointCount * 3), 3));
    geometry.setDrawRange(0, pointCount);
    geometries.add(geometry);

    const fiber = new THREE.Line(
      geometry,
      family === 'longitudinal' ? longitudinalMaterial : transverseMaterial
    );
    fiber.frustumCulled = false;
    fiber.userData = {
      family,
      index,
      total,
      points: pointCount,
      phase: index * 0.76
    } satisfies FiberMeta;
    fibers.add(fiber);
  }

  for (let i = 0; i < longitudinalCount; i += 1) addFiber('longitudinal', i, longitudinalCount);
  for (let i = 0; i < transverseCount; i += 1) addFiber('transverse', i, transverseCount);
  world.add(fibers);

  const seedPoint = new THREE.Vector3();
  const skinPoint = new THREE.Vector3();

  function updateFiber(line: THREE.Line, direction: Direction): void {
    const meta = line.userData as FiberMeta;
    const position = line.geometry.getAttribute('position') as THREE.BufferAttribute;

    for (let j = 0; j < meta.points; j += 1) {
      const u = j / (meta.points - 1);
      const coil = meta.phase + u * Math.PI * 1.4;
      const coilRadius = 0.025 + u * 0.12;
      seedPoint.set(
        direction.seedPosition.x + Math.cos(coil) * coilRadius,
        direction.seedPosition.y + (u - 0.5) * 0.46 + Math.sin(coil) * 0.018,
        direction.seedPosition.z + Math.sin(coil) * coilRadius
      );

      if (meta.family === 'longitudinal') {
        const lane = (meta.index + 0.5) / meta.total;
        const angle = 0.18 + lane * (Math.PI - 0.36);
        const radius = 2.08 - u * 0.12;
        skinPoint.set(
          Math.cos(angle) * radius,
          -1.52 + Math.sin(angle) * (1.92 + direction.canopyBreath),
          -0.76 - u * 2.95
        );
      } else {
        const depth = (meta.index + 0.7) / meta.total;
        const angle = 0.18 + u * (Math.PI - 0.36);
        const radius = 2.08 - depth * 0.12;
        skinPoint.set(
          Math.cos(angle) * radius,
          -1.52 + Math.sin(angle) * (1.92 + direction.canopyBreath),
          -0.76 - depth * 2.95
        );
      }

      const directionalDelay = meta.family === 'longitudinal' ? u * 0.3 : 0.12 + u * 0.18;
      const growth = smooth01(direction.fiberAssembly * 1.35 - directionalDelay);
      position.setXYZ(
        j,
        THREE.MathUtils.lerp(seedPoint.x, skinPoint.x, growth),
        THREE.MathUtils.lerp(seedPoint.y, skinPoint.y, growth),
        THREE.MathUtils.lerp(seedPoint.z, skinPoint.z, growth)
      );
    }

    position.needsUpdate = true;
  }

  function render(direction: Direction): void {
    camera.position.copy(direction.camera);
    camera.lookAt(direction.target);

    for (const child of fibers.children) updateFiber(child as THREE.Line, direction);

    const emergence = smooth01((direction.story - 0.08) / 0.18);
    const retirement = 1 - smooth01((direction.story - 0.72) / 0.24);
    fibers.visible = emergence > 0.001 && retirement > 0.001;
    longitudinalMaterial.opacity = emergence * retirement * (0.08 + direction.fiberAssembly * 0.19);
    transverseMaterial.opacity = emergence * retirement * direction.fiberAssembly * 0.11;

    renderer.render(world, camera);
  }

  function resize(next: GeneratedViewport): void {
    camera.aspect = next.width / next.height;
    camera.updateProjectionMatrix();
    renderer.setPixelRatio(Math.min(next.dpr, quality === 'low' ? 1.25 : 2));
    renderer.setSize(next.width, next.height, false);
  }

  function dispose(): void {
    geometries.forEach((geometry) => geometry.dispose());
    materials.forEach((material) => material.dispose());
    renderer.dispose();
  }

  return { render, resize, dispose };
}

